import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BGlkWkwp.js";const g=JSON.parse('{"title":"Shell","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/shell.md","filePath":"workbench/shell.md"}'),s={name:"workbench/shell.md"};function h(c,e,i,n,r,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="shell" tabindex="-1">Shell <a class="header-anchor" href="#shell" aria-label="Permalink to &quot;Shell&quot;">​</a></h1><p>Shell is the frame of a drawing application: the bar at the top, a region on each side, the stage in the middle, the toolbar over the bottom of the stage and a dock under it, with the keyboard shortcuts of the whole screen.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it once, as the whole screen of a drawing application. Each region is a snippet and any may be absent: the application passes a <a href="./../components/topbar">Topbar</a> in <code>top</code>, a <a href="./../components/panel">Panel</a> in <code>left</code> and in <code>right</code>, a <a href="./../components/drawbar">Drawbar</a> in <code>bottom</code>, a Panel with <code>side=&quot;fill&quot;</code> in <code>dock</code>, and whatever it draws on in <code>stage</code>. The shell places them and moves the side regions as the window narrows; it knows nothing of what they hold. A special mode of the application, such as a print preview or an older version, is a change of what the application passes in <code>stage</code> and the side regions, not a mode of the shell.</p><p>By default the side regions float over the stage, as they do in the editor of the reference application; <code>side=&quot;beside&quot;</code> stands them beside the stage on a wide screen instead.</p><p>Use <code>overlay</code> when the shell lies over a drawing surface that the page owns, such as a map that is not passed in <code>stage</code>: the shell lets the pointer through to it everywhere but its regions.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>side</code></td><td><code>&#39;floating&#39;</code></td><td>From 64rem, <code>&#39;floating&#39;</code> or <code>&#39;beside&#39;</code></td></tr><tr><td><code>narrow</code></td><td></td><td><code>true</code>: the narrow form at any width; <code>false</code>: never</td></tr><tr><td><code>leftOpen</code></td><td><code>true</code></td><td>Whether the left region shows (bindable)</td></tr><tr><td><code>rightOpen</code></td><td><code>false</code></td><td>Whether the right region shows (bindable)</td></tr><tr><td><code>dockHeight</code></td><td></td><td>The dock&#39;s height in px (bindable); 38.2% without it</td></tr><tr><td><code>shortcuts</code></td><td><code>[]</code></td><td>The keyboard shortcuts, <code>Shortcut[]</code></td></tr><tr><td><code>shortcutsOpen</code></td><td><code>false</code></td><td>Whether the list of shortcuts is open (bindable)</td></tr><tr><td><code>groups</code></td><td></td><td>The order of the groups in the list of shortcuts</td></tr><tr><td><code>overlay</code></td><td><code>false</code></td><td>Lets the pointer through, except on its regions</td></tr><tr><td><code>leftLabel</code></td><td></td><td>The name of the left region&#39;s sheet</td></tr><tr><td><code>rightLabel</code></td><td></td><td>The name of the right region&#39;s sheet</td></tr><tr><td><code>leftSheet</code></td><td></td><td>The left sheet&#39;s heights and closing, <code>ShellSheet</code></td></tr><tr><td><code>rightSheet</code></td><td></td><td>The right sheet&#39;s heights and closing, <code>ShellSheet</code></td></tr><tr><td><code>leftStage</code></td><td><code>&#39;half&#39;</code></td><td>The left sheet&#39;s height while open (bindable)</td></tr><tr><td><code>rightStage</code></td><td><code>&#39;half&#39;</code></td><td>The right sheet&#39;s height while open (bindable)</td></tr><tr><td><code>leftReopen</code></td><td></td><td>A control that opens the closed left region, <code>ShellReopen</code></td></tr><tr><td><code>rightReopen</code></td><td></td><td>A control that opens the closed right region</td></tr><tr><td><code>bottomFab</code></td><td></td><td>Folds the toolbar into a Fab when narrow, <code>ShellFab</code></td></tr><tr><td><code>dockSheet</code></td><td></td><td>The dock&#39;s sheet when narrow, <code>ShellDockSheet</code></td></tr><tr><td><code>ondockclose</code></td><td></td><td>Called when the dock&#39;s sheet closes</td></tr><tr><td><code>topFloating</code></td><td><code>false</code></td><td>The bar floats over the stage when narrow</td></tr><tr><td><code>onlayout</code></td><td></td><td>Called with <code>{ width, leftMode, rightMode, inset }</code> on change</td></tr><tr><td><code>onescape</code></td><td></td><td>Called with Escape when no sheet is left to close</td></tr></tbody></table><p><code>width</code> is <code>wide</code>, <code>mid</code> or <code>narrow</code>, and each mode is <code>beside</code>, <code>floating</code> or <code>sheet</code> (<code>ShellLayout</code>, <code>ShellWidth</code> and <code>ShellMode</code>; the type of <code>side</code> is <code>ShellSide</code>). <code>inset</code> is <code>{ top, right, bottom, left }</code> in px: what the regions cover of the stage, from each edge of the stage to the inner edge of the region on that side (see <a href="#inset">Inset</a>). <code>onescape</code> returns <code>false</code> to leave the key to the browser.</p><p>A <code>ShellSheet</code> is <code>{ stages?, closable? }</code>: <code>stages</code> are the heights the sheet offers, lowest first (<code>SheetStage[]</code>, all three by default), and <code>closable: false</code> keeps the sheet when it is dragged below the lowest height (it closes by default). A stage is <code>peek</code>, <code>half</code> or <code>full</code> (<code>SheetStage</code>).</p><p>A <code>ShellReopen</code> is <code>{ icon, label }</code>: an icon name or component, and the name of the control. A <code>ShellFab</code> is <code>{ label, closeLabel, icon? }</code>: the name of the Fab while the toolbar is hidden and while it shows, and its icon while the toolbar is hidden (<code>plus</code> by default; <code>x</code> while it shows). A <code>ShellDockSheet</code> is <code>{ label, stages? }</code>: the name of the sheet and the heights it offers, lowest first (<code>half</code> and <code>full</code> by default).</p><p>A <code>Shortcut</code> is <code>{ key, label, run, when?, group?, aliases?, hidden?, display? }</code>. <code>key</code> is written without regard to the platform: modifiers joined with <code>+</code>, then one key, such as <code>mod+z</code>, <code>shift+mod+z</code>, <code>alt+l</code> or <code>?</code>; <code>mod</code> is ⌘ on a Mac and Ctrl elsewhere, and named keys are <code>escape</code>, <code>enter</code>, <code>tab</code>, <code>space</code>, <code>backspace</code>, <code>delete</code>, <code>plus</code>, <code>minus</code>, the arrows <code>up</code>, <code>down</code>, <code>left</code> and <code>right</code>, <code>home</code>, <code>end</code>, <code>pageup</code>, <code>pagedown</code> and <code>f1</code> to <code>f12</code>. <code>digit</code> is any of the keys 0 to 9, and <code>run</code> reads which one from the key event. A modifier alone (<code>alt</code>, <code>shift</code> or <code>mod</code>) is the press of that key with no other key. A letter, a digit, a symbol such as <code>[</code> or <code>/</code>, <code>plus</code> and <code>minus</code> also match by the physical key, so that they still count when ⌥ on a Mac turns them into another character. <code>run</code> is called with the key event; when it returns <code>false</code> the key goes on to the next shortcut with the same key, and to the browser. <code>when</code> says whether the shortcut acts now, and <code>group</code> is the heading it is listed under.</p><table tabindex="0"><thead><tr><th>Key</th><th>Description</th></tr></thead><tbody><tr><td><code>aliases</code></td><td>More keys that run it, not listed (<code>backspace</code> for <code>delete</code>)</td></tr><tr><td><code>hidden</code></td><td>It runs but is not listed</td></tr><tr><td><code>display</code></td><td>The keys listed instead of <code>key</code>, joined with &quot; / &quot;</td></tr></tbody></table><p><code>formatShortcut(key)</code> writes a key as the platform does (⇧⌘Z on a Mac, Ctrl+Shift+Z elsewhere; <code>digit</code> as 0–9, and a modifier alone as ⌥ or Alt), for a tooltip or a menu, and <code>isMacPlatform()</code> says whether the platform is a Mac, where <code>mod</code> is ⌘. The shell&#39;s own matching is exported for the application&#39;s tests and its own listeners: <code>matchesShortcut(key, event)</code> says whether a key event is that key, <code>matchesAnyShortcut(shortcut, event)</code> whether it is the key or one of the aliases of a shortcut, and <code>shortcutText(shortcut)</code> writes its keys as the list does.</p><h2 id="snippets" tabindex="-1">Snippets <a class="header-anchor" href="#snippets" aria-label="Permalink to &quot;Snippets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Snippet</th><th>Holds</th></tr></thead><tbody><tr><td><code>top</code></td><td>The bar at the top, a Topbar</td></tr><tr><td><code>left</code></td><td>The left region, a Panel</td></tr><tr><td><code>right</code></td><td>The right region, a Panel</td></tr><tr><td><code>stage</code></td><td>The drawing surface; it fills the rest</td></tr><tr><td><code>bottom</code></td><td>The toolbar over the bottom of the stage, a Drawbar</td></tr><tr><td><code>dock</code></td><td>The area under the stage, a Panel with <code>side=&quot;fill&quot;</code></td></tr><tr><td><code>veil</code></td><td>While given, it covers the stage in a <a href="./../components/veil">Veil</a></td></tr></tbody></table><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>The side regions follow the three widths of the layout, measured in rem so that a larger text size counts as a narrower window. The shell measures its own element, not the window, and it is the size container <code>app</code> of everything inside it, so the components in its regions follow the shell&#39;s width too, with or without the base CSS. When the browser has no <code>ResizeObserver</code>, it measures the window.</p><ul><li>From 48rem, the side regions float over the stage, each in a <a href="./../components/floating">Floating</a> gap-md from the top of the stage and from its own side. A pane is a panel wide (<code>--kata-width-panel</code>) and no wider than the stage less gap-md on each side. It is as tall as what it holds, up to the height of the stage less gap-md above and below; beyond that the content of the Panel in it scrolls. Both may be open at once, there is no scrim, and the stage takes the pointer wherever a pane is not. At 48rem two panes and the three gaps around them fill the stage exactly.</li><li>With <code>side=&quot;beside&quot;</code>, from 64rem the side regions stand beside the stage instead, as tall as the space under the bar, with a strong line towards the stage; from 48 to 64rem they float as above.</li><li>Below 48rem, each is a <a href="./../components/sheet">Sheet</a> from the bottom of the stage, and the toolbar rises to stay above the sheets.</li></ul><table tabindex="0"><thead><tr><th>Width</th><th><code>side=&quot;floating&quot;</code></th><th><code>side=&quot;beside&quot;</code></th></tr></thead><tbody><tr><td>From 64rem (<code>wide</code>)</td><td><code>floating</code></td><td><code>beside</code></td></tr><tr><td>48 to 64rem (<code>mid</code>)</td><td><code>floating</code></td><td><code>floating</code></td></tr><tr><td>Below 48rem (<code>narrow</code>)</td><td><code>sheet</code></td><td><code>sheet</code></td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The top bar keeps its height. Under it, the side regions and a column of the stage and the dock fill the rest; the stage is the positioned frame of everything that lies over the drawing: the toolbar, the floating panes, the sheets and the veil. The dock is under the stage with a strong line along its top, at least a toolbar high, and it leaves the stage a toolbar&#39;s height at least. Its top edge is a grip without a look: a drag changes <code>dockHeight</code>, the arrow keys move it by 32px, and the value that is kept is the height after those limits. The grip&#39;s name is the <code>dockHeight</code> message. The floating panes lie over the stage, which is above the dock, so their limit leaves the dock out.</p><p>The shortcuts are attached to the document while the shell is mounted. The first shortcut whose key matches and whose <code>when</code> holds runs. The help key (?, the Help key or F1) opens a <a href="./shortcuts-modal">ShortcutsModal</a> that lists them, unless a shortcut takes the key first. Escape closes the sheet that was opened last and returns the focus to where it was when that sheet opened; when none is open, it goes to <code>onescape</code>. The floating panes and the panels beside the stage stay open on Escape, which goes straight to <code>onescape</code>. Keys typed into a field, keys an input method is composing, keys already handled (<code>defaultPrevented</code>) and keys pressed while a modal dialog or a popover is open belong to them, not to the shell.</p><p>With <code>overlay</code>, the root and the stage have <code>pointer-events: none</code>, and the bar, the side regions, the toolbar, the dock, the floating panes, the sheets, the veil and the list of shortcuts have <code>pointer-events: auto</code>. What the application passes in <code>stage</code> lets the pointer through too.</p><p>With <code>narrow</code>, the shell takes the narrow form at any width: the side regions are sheets and <code>onlayout</code> reports the width as <code>narrow</code>, as for a short window or a shell embedded in a small frame. With <code>narrow={false}</code> it never does: below 48rem the width is <code>mid</code> and the side regions float. Without it, the width decides.</p><p>On a narrow screen, <code>leftSheet</code> and <code>rightSheet</code> set the heights each side&#39;s sheet offers and whether it closes. A sheet with <code>closable: false</code> does not close below its lowest height, and while its region is not open (<code>leftOpen</code> or <code>rightOpen</code> is false) it stays at that height, so that its head still shows; raising it opens the region again. It rests under the sheets that are open, Escape passes it by, and the toolbar rises above it too. <code>leftStage</code> and <code>rightStage</code> are the height of each sheet while its region is open: the application reads them and can set them, to lower a sheet to its lowest height instead of closing it, say.</p><p>From 48rem, <code>leftReopen</code> and <code>rightReopen</code> put a control in the corner of the stage on their side while that region is closed: a ghost icon button in a <a href="./../components/floating">Floating</a> gap-md from the top and from the side, which sets <code>leftOpen</code> or <code>rightOpen</code> when pressed. It shows only when the region is given. The narrow form has none: a sheet that does not close keeps its head, and the application has its own way in otherwise.</p><p>With <code>bottomFab</code>, the narrow form folds the toolbar into a <a href="./../components/fab">Fab</a>, gap-md from the right of the stage and from the top of the sheets. A press on the Fab shows the toolbar above it, gap-md apart and gap-md from the right, and another press hides it; while it shows, the Fab&#39;s name is <code>closeLabel</code> and its icon <code>x</code>. The <code>bottom</code> snippet receives <code>{ column }</code>, true while the toolbar stands in one column above the Fab and false elsewhere: pass it to the Drawbar&#39;s <code>column</code>. A snippet that takes no argument works as before. The column stays between gap-md below the top inset of the stage and gap-md above the Fab, and scrolls when it does not fit there, its scrollbar beside the tools. From 48rem the toolbar stays over the bottom of the stage.</p><p>The narrow form puts the dock in a <a href="./../components/sheet">Sheet</a> named <code>dock</code> instead of the area under the stage; <code>dockSheet</code> gives the sheet&#39;s name and heights (without it, the <code>dock</code> message and <code>half</code> and <code>full</code>). The sheet holds the dock as a panel, opens at the lowest of its heights and closes below it; it then calls <code>ondockclose</code>, and the application removes the dock. It lies under the side sheets that are open; a resting sheet is not shown while the dock&#39;s sheet is open. The toolbar rises above it as above them. <code>dockHeight</code> and the grip belong to the dock under the stage only.</p><p>On a narrow screen one of the side sheets and the dock is open at a time. Opening a side sheet closes the other side (its <code>leftOpen</code> or <code>rightOpen</code> becomes false) and the dock (<code>ondockclose</code> is called); the dock&#39;s sheet coming, when the application gives the dock or the screen narrows with it, closes the side sheets. A sheet that rests at its lowest height (<code>closable: false</code>) does not count as open: it is not shown while the dock&#39;s sheet is open, and comes back when the dock closes. When the screen narrows with both side regions open, the one opened last stays, the right one at mount.</p><p>With <code>topFloating</code>, the narrow form floats the bar over the stage in a <a href="./../components/floating">Floating</a> gap-md from the top of the stage and from each side, instead of keeping its height above it; the frame of the Floating is the bar&#39;s only line. The stage then fills the shell, and the drawing shows under the bar. The root then sets <code>--kata-shell-top</code> to the bar&#39;s height plus gap-md, the top inset of the stage, for what lies over the stage below the bar. From 48rem the bar keeps its place.</p><h2 id="inset" tabindex="-1">Inset <a class="header-anchor" href="#inset" aria-label="Permalink to &quot;Inset&quot;">​</a></h2><p><code>onlayout</code> reports, in <code>inset</code>, what the regions cover of the stage, so that the application can keep what it draws in view (the padding of a map&#39;s camera, say). Each side is the distance in px from that edge of the stage to the inner edge of the region on that side.</p><ul><li><code>left</code> and <code>right</code>: beside the stage, the width of the open side region; floating, the pane&#39;s box and the gap-md before it; as a sheet, 0.</li><li><code>bottom</code>: the height of the sheets the toolbar rises above.</li><li><code>top</code>: with <code>topFloating</code> on a narrow screen, the bar&#39;s box and the gap-md above it.</li></ul><p>Only an open side region counts: a sheet that rests at its lowest height (<code>closable: false</code>) does not, and neither does a closed region&#39;s control to open it again. <code>bottom</code> leaves out the column of the toolbar above the Fab (<code>bottomFab</code>); it is 0 from 48rem. <code>top</code> is 0 when the bar keeps its place above the stage.</p><p>The shell measures these with a <code>ResizeObserver</code> (read in the delivery and written in the next frame), and calls <code>onlayout</code> when the width, a mode or the inset changes. The root also sets them as <code>--kata-shell-inset-top</code>, <code>--kata-shell-inset-right</code>, <code>--kata-shell-inset-bottom</code> and <code>--kata-shell-inset-left</code>, in px, for what lies over the stage.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/shell/" title="Shell" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/shell/" target="_blank" rel="noopener">Shell</a></figcaption></figure>',38)])])}const f=t(s,[["render",h]]);export{g as __pageData,f as default};
